      'Собственная разработка — от библиотеки распознавания номеров до городских платформ данных. Нажмите на карточку, чтобы посмотреть состав продукта.': 'Собственная разработка — от библиотеки распознавания номеров до городских платформ данных. Нажмите на карточку, чтобы посмотреть состав продукта.',
