      'В какой роли компания входит в проект и что получает партнёр в каждом случае.': '公司以何种角色参与项目，以及合作伙伴在每种情况下获得什么。',
      'Шесть разделов с деталями. Нажмите на карточку — откроется отдельная страница.': '六个详细板块。点击卡片可打开独立页面。',
      'Нажмите на карточку — откроется полная характеристика, техпаспорт и фотографии.': '点击卡片可查看完整参数、技术护照与照片。',
      'Десять типичных ситуаций и услуга, которая закрывает каждую. Найдите свою — рядом будет решение.': '十种典型情形以及对应的解决服务。找到您的情形，旁边就是方案。',
      'Так выглядит работа системы: комплексы фиксируют нарушения и передают материал в центр обработки.': '系统的运行方式：设备抓拍违法行为并将材料传输至处理中心。',
      'Представьтесь, пожалуйста — так мы сможем ответить именно вам. Ответ оператора появится здесь, в чате.': '请先介绍一下自己，这样我们才能准确回复您。客服的回答将显示在这里。',
      'Объекты, где комплексы уже работают: магистрали, перекрёстки, выделенные полосы и железнодорожные переезды.': '设备已在运行的场所：干线公路、路口、专用车道和铁路道口。',
      'Семь направлений: от фиксации нарушений и видеоаналитики до городских платформ, связи и локализации производства.': '七个方向：从违法抓拍和视频分析，到城市平台、通信与生产本地化。',
      'Откройте каталог комплексов по типам нарушений или свяжитесь с нами — поможем с выбором и подготовим предложение.': '按违法类型浏览设备目录，或直接联系我们——我们会协助选型并准备报价。',
      'Подробное описание этого раздела ещё готовится. Напишите нам — расскажем в деталях применительно к вашему объекту.': '该板块的详细说明仍在准备中。请与我们联系，我们会结合您的项目详细介绍。',
      'Найдите свою ситуацию — рядом стоит услуга, которая её закрывает. Фиксация нарушений это только одно из направлений.': '找到您的情形——旁边就是解决它的服务。违法抓拍只是我们的方向之一。',
      'В какой роли компания входит в проект: разработчик, производитель, интегратор, оператор или технологический партнёр.': '公司以何种角色参与项目：开发方、制造方、集成商、运营方或技术合作伙伴。',
      'Все ключевые компетенции собраны в едином контуре ответственности. Нажмите на карточку — откроется подробное описание.': '所有核心能力集中在同一个责任闭环内。点击卡片查看详细说明。',
      'Десять этапов инфраструктурного проекта — от обследования площадки до интеграции с государственными системами и сервиса по SLA.': '基础设施项目的十个阶段——从场地勘查到与政府系统对接以及 SLA 运维。',
      'Разработка, электроника, метрология, полевая инфраструктура, проектный офис и коммерциализация в одном контуре ответственности.': '研发、电子、计量、现场基础设施、项目办公室与商业化，集中在同一个责任闭环内。',
      'Собственная разработка — от библиотеки распознавания номеров до городских платформ данных. Нажмите на карточку, чтобы посмотреть состав продукта.': '自主研发——从车牌识别程序库到城市数据平台。点击卡片查看产品构成。',
      'Компания закрывает не одну задачу, а весь контур: фиксация нарушений, видеоаналитика, городские платформы, связь, взимание платы за проезд, мониторинг с БПЛА и локализация производства.': '公司覆盖的不是单一任务，而是整个闭环：违法抓拍、视频分析、城市平台、通信、道路收费、无人机监测与生产本地化。',
      'Оборудование выпускается на собственном производстве, поэтому вы покупаете напрямую, без посредников и лишних наценок. Каждый комплекс проходит контроль качества и поставляется с гарантией, полным комплектом документов и сертификатами соответствия.': '设备在我们自有工厂生产，因此您可直接采购，没有中间商和额外加价。每套设备都经过质量检验，并附带保修、全套文件和合格证书。',
      'Мы производим программно-аппаратные комплексы фиксации нарушений ПДД — от схемотехники и встроенного программного обеспечения до серийной сборки и выпускного контроля качества. Это собственная разработка, а не перепродажа чужого оборудования под своей маркой.': '我们制造交通违法抓拍软硬件系统——从电路设计和嵌入式软件到批量组装与出厂质检。这是自主研发，而非贴牌转售他人的设备。',
      'За более чем 15 лет работы наши комплексы были поставлены на городские дороги, магистрали и объекты транспортной инфраструктуры. Мы делаем ставку на надёжность, точность измерений и долгий срок службы оборудования в любых климатических условиях — от −50 °C до +70 °C.': '在超过 15 年的经营中，我们的设备已部署在城市道路、干线公路和交通基础设施上。我们看重可靠性、测量精度以及设备在各种气候条件下的长寿命——从 −50 °C 到 +70 °C。',
      'OLAN HIGH TECH PROJECT — производитель и поставщик интеллектуальных комплексов автоматической фиксации нарушений правил дорожного движения. Мы выпускаем сертифицированное оборудование для контроля скорости, проезда на красный свет, нарушений правил парковки, проезда железнодорожных переездов и выезда на полосу общественного транспорта.': 'OLAN HIGH TECH PROJECT 是交通违法自动抓拍智能系统的制造商与供应商。我们生产经过认证的设备，用于测速、闯红灯、违章停车、铁路道口通行以及公交专用道抓拍。',
